// Process product data and create embedding text
const items = $input.all();
const processedItems = [];

for (const item of items) {
  const product = item.json;

  // Combine relevant fields for embedding text
  const embeddingText = [
    `Product Name: ${product.name || ''}`,
    `Description: ${product.description || ''}`,
    `Category: ${product.category || ''}`,
    `Allergens: ${product.allergens || 'None'}`,
    `Nutritional Info: ${product.nutritional_info || ''}`
  ].filter(text => text.split(': ')[1]).join(' | ');

  // Prepare metadata object
  const metadata = {
    product_code: product.product_code || '',
    brand: product.brand || '',
    country_of_origin: product.country_of_origin || '',
    vendor_name: product.vendor_name || '',
    shelf_life: product.shelf_life || '',
    storage_requirements: product.storage_requirements || ''
  };

  // Create output item
  processedItems.push({
    json: {
      text: embeddingText,
      metadata: metadata
    }
  });
}

return processedItems;

// Filter and rank results based on allergen profile, storage location, and brand preferences

// Get input items from vector store retrieval
const results = $input.all();

// Get search parameters from previous nodes
const searchParams = $('Extract Search Parameters').first().json;

// Extract filter criteria
const allergenProfile = searchParams.allergenProfile || [];
const storageLocation = searchParams.storageLocation || '';
const brandPreferences = searchParams.brandPreferences || [];

// Filter results
const filteredResults = results.filter(item => {
  const product = item.json;

  // Check allergen compatibility
  const productAllergens = product.allergens || [];
  const hasAllergenConflict = allergenProfile.some(allergen => 
    productAllergens.includes(allergen)
  );

  if (hasAllergenConflict) {
    return false;
  }

  // Check storage location match (if specified)
  if (storageLocation && product.storageLocation !== storageLocation) {
    return false;
  }

  return true;
});

// Rank results by similarity score and preference matching
const rankedResults = filteredResults.map(item => {
  const product = item.json;
  let score = product.similarityScore || 0;

  // Boost score for brand preferences
  if (brandPreferences.includes(product.brand)) {
    score += 0.1;
  }

  // Boost score for exact storage location match
  if (storageLocation && product.storageLocation === storageLocation) {
    score += 0.05;
  }

  return {
    ...item,
    json: {
      ...product,
      finalScore: score
    }
  };
});

// Sort by final score (descending)
rankedResults.sort((a, b) => b.json.finalScore - a.json.finalScore);

// Return top 5 results
const topResults = rankedResults.slice(0, 5);

return topResults;

// Generate natural language reasoning for each substitute product
const items = $input.all();
const results = [];

for (const item of items) {
  const product = item.json;

  // Extract key attributes for comparison
  const originalProduct = product.originalProduct || {};
  const substituteProduct = product.substituteProduct || {};

  // Build reasoning text comparing key attributes
  let reasoning = `This ${substituteProduct.name || 'product'} is a suitable substitute because:\n\n`;

  // Compare origin
  if (substituteProduct.origin && originalProduct.origin) {
    if (substituteProduct.origin === originalProduct.origin) {
      reasoning += `✓ Same origin (${substituteProduct.origin})\n`;
    } else {
      reasoning += `• Different origin: ${substituteProduct.origin} vs ${originalProduct.origin}\n`;
    }
  }

  // Compare allergens
  if (substituteProduct.allergens && originalProduct.allergens) {
    const subAllergens = Array.isArray(substituteProduct.allergens) ? substituteProduct.allergens : [];
    const origAllergens = Array.isArray(originalProduct.allergens) ? originalProduct.allergens : [];

    if (subAllergens.length === 0 && origAllergens.length === 0) {
      reasoning += `✓ No allergens in both products\n`;
    } else if (subAllergens.length < origAllergens.length) {
      reasoning += `✓ Fewer allergens (${subAllergens.length} vs ${origAllergens.length})\n`;
    } else if (subAllergens.length === origAllergens.length) {
      reasoning += `• Same number of allergens (${subAllergens.length})\n`;
    } else {
      reasoning += `⚠ More allergens (${subAllergens.length} vs ${origAllergens.length})\n`;
    }
  }

  // Compare fat content
  if (substituteProduct.fatContent !== undefined && originalProduct.fatContent !== undefined) {
    const fatDiff = substituteProduct.fatContent - originalProduct.fatContent;
    if (Math.abs(fatDiff) < 1) {
      reasoning += `✓ Similar fat content (${substituteProduct.fatContent}g vs ${originalProduct.fatContent}g)\n`;
    } else if (fatDiff < 0) {
      reasoning += `✓ Lower fat content (${substituteProduct.fatContent}g vs ${originalProduct.fatContent}g)\n`;
    } else {
      reasoning += `• Higher fat content (${substituteProduct.fatContent}g vs ${originalProduct.fatContent}g)\n`;
    }
  }

  // Compare customer ratings
  if (substituteProduct.rating !== undefined && originalProduct.rating !== undefined) {
    const ratingDiff = substituteProduct.rating - originalProduct.rating;
    if (ratingDiff >= 0.5) {
      reasoning += `✓ Higher customer rating (${substituteProduct.rating}/5 vs ${originalProduct.rating}/5)\n`;
    } else if (Math.abs(ratingDiff) < 0.5) {
      reasoning += `✓ Similar customer rating (${substituteProduct.rating}/5 vs ${originalProduct.rating}/5)\n`;
    } else {
      reasoning += `• Lower customer rating (${substituteProduct.rating}/5 vs ${originalProduct.rating}/5)\n`;
    }
  }

  // Add similarity score if available
  if (product.similarityScore !== undefined) {
    reasoning += `\nSimilarity score: ${(product.similarityScore * 100).toFixed(1)}%`;
  }

  // Format output with product details and reasoning
  results.push({
    json: {
      productId: substituteProduct.id || substituteProduct.productId,
      productName: substituteProduct.name,
      productDetails: {
        origin: substituteProduct.origin,
        allergens: substituteProduct.allergens,
        fatContent: substituteProduct.fatContent,
        rating: substituteProduct.rating,
        price: substituteProduct.price,
        category: substituteProduct.category
      },
      originalProductDetails: {
        name: originalProduct.name,
        origin: originalProduct.origin,
        allergens: originalProduct.allergens,
        fatContent: originalProduct.fatContent,
        rating: originalProduct.rating
      },
      reasoning: reasoning,
      similarityScore: product.similarityScore,
      metadata: product.metadata || {}
    }
  });
}

return results;

// Detect customer language from CRM preference or phone country code
// Supports Finnish (fi), Swedish (sv), English (en)
// Defaults to Finnish if detection fails

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;

  let detectedLanguage = 'fi'; // Default to Finnish

  // Try to get language from CRM preference
  if (data.customerLanguage) {
    const lang = data.customerLanguage.toLowerCase();
    if (['fi', 'sv', 'en'].includes(lang)) {
      detectedLanguage = lang;
    } else if (lang.includes('finnish') || lang.includes('suomi')) {
      detectedLanguage = 'fi';
    } else if (lang.includes('swedish') || lang.includes('svenska')) {
      detectedLanguage = 'sv';
    } else if (lang.includes('english')) {
      detectedLanguage = 'en';
    }
  }
  // Try to detect from phone country code
  else if (data.phoneCountryCode || data.countryCode) {
    const countryCode = (data.phoneCountryCode || data.countryCode).toUpperCase();

    // Map country codes to languages
    if (countryCode === 'FI' || countryCode === '+358' || countryCode === '358') {
      detectedLanguage = 'fi';
    } else if (countryCode === 'SE' || countryCode === '+46' || countryCode === '46') {
      detectedLanguage = 'sv';
    } else if (['US', 'GB', 'UK', 'CA', 'AU', 'NZ', '+1', '+44'].includes(countryCode)) {
      detectedLanguage = 'en';
    }
  }
  // Try to detect from phone number prefix
  else if (data.phoneNumber) {
    const phone = data.phoneNumber.replace(/\s+/g, '');
    if (phone.startsWith('+358') || phone.startsWith('358')) {
      detectedLanguage = 'fi';
    } else if (phone.startsWith('+46') || phone.startsWith('46')) {
      detectedLanguage = 'sv';
    } else if (phone.startsWith('+1') || phone.startsWith('+44')) {
      detectedLanguage = 'en';
    }
  }

  results.push({
    json: {
      ...data,
      detectedLanguage: detectedLanguage,
      languageName: detectedLanguage === 'fi' ? 'Finnish' : detectedLanguage === 'sv' ? 'Swedish' : 'English'
    }
  });
}

return results;

=// Multilingual script templates
const templates = {
  finnish: {
    greeting: "Hei! Tämä on {{store_name}}.",
    productUnavailable: "Valitettavasti tuote {{product_name}} ei ole tällä hetkellä saatavilla.",
    substitutionOffer: "Voimme kuitenkin tarjota korvaavan tuotteen: {{substitute_name}}.",
    comparison: "Tämä tuote on samanlainen kuin alkuperäinen, mutta {{comparison_details}}.",
    delivery: "Toimitus tapahtuu {{delivery_date}}.",
    question: "Haluaisitko hyväksyä tämän korvaavan tuotteen?"
  },
  swedish: {
    greeting: "Hej! Det här är {{store_name}}.",
    productUnavailable: "Tyvärr är produkten {{product_name}} inte tillgänglig för tillfället.",
    substitutionOffer: "Vi kan dock erbjuda en ersättningsprodukt: {{substitute_name}}.",
    comparison: "Denna produkt är liknande den ursprungliga, men {{comparison_details}}.",
    delivery: "Leverans sker {{delivery_date}}.",
    question: "Vill du acceptera denna ersättningsprodukt?"
  },
  english: {
    greeting: "Hello! This is {{store_name}}.",
    productUnavailable: "Unfortunately, the product {{product_name}} is currently unavailable.",
    substitutionOffer: "However, we can offer a substitute product: {{substitute_name}}.",
    comparison: "This product is similar to the original, but {{comparison_details}}.",
    delivery: "Delivery will be on {{delivery_date}}.",
    question: "Would you like to accept this substitute product?"
  }
};

// Get input data
const language = $input.item.json.detected_language || 'english';
const productName = $input.item.json.product_name || 'the requested product';
const substituteName = $input.item.json.substitute_name || 'a similar product';
const storeName = $input.item.json.store_name || 'your local store';
const deliveryDate = $input.item.json.delivery_date || 'soon';
const comparisonDetails = $input.item.json.comparison_details || 'has similar features';

// Select template based on detected language
const template = templates[language.toLowerCase()] || templates.english;

// Replace template variables with actual values
const replaceVariables = (text, variables) => {
  return text
    .replace(/{{product_name}}/g, variables.product_name)
    .replace(/{{substitute_name}}/g, variables.substitute_name)
    .replace(/{{store_name}}/g, variables.store_name)
    .replace(/{{delivery_date}}/g, variables.delivery_date)
    .replace(/{{comparison_details}}/g, variables.comparison_details);
};

const variables = {
  product_name: productName,
  substitute_name: substituteName,
  store_name: storeName,
  delivery_date: deliveryDate,
  comparison_details: comparisonDetails
};

// Generate complete script
const script = [
  replaceVariables(template.greeting, variables),
  replaceVariables(template.productUnavailable, variables),
  replaceVariables(template.substitutionOffer, variables),
  replaceVariables(template.comparison, variables),
  replaceVariables(template.delivery, variables),
  replaceVariables(template.question, variables)
].join(' ');

// Return the generated script
return {
  json: {
    language: language,
    script: script,
    product_name: productName,
    substitute_name: substituteName,
    delivery_date: deliveryDate
  }
};
